INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q0','nism-8-z0','According to the Cost-of-Carry model for pricing index futures, what does the fair futures price equal?','["Spot Price - Carry Costs + Dividends","Spot Price + Cost of Financing - Dividend Yield","Strike Price + Option Premium - Margin Interest","Spot Price / Risk-Free Interest Rate"]',1,'Fair Futures Price = Spot Price + Cost of Carry - Inflows (Dividends) = S * [1 + r*(t/365)] - D.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q1','nism-8-z0','Which option Greek measures the rate of change of Delta with respect to a change in the price of the underlying asset?','["Theta","Vega","Gamma","Rho"]',2,'Gamma represents the first derivative of Delta with respect to the underlying spot price. It measures the curvature or convexity of the option price.',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q2','nism-8-z0','What is the maximum potential loss for an investor who buys an Out-of-the-Money (OTM) European Call option?','["Unlimited down to zero","Limited strictly to the initial premium paid","The strike price minus spot price","The SPAN margin deposited with clearing member"]',1,'For a call option buyer, downside risk is strictly limited to the premium paid to enter the contract, while upside gain is theoretically unlimited.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q3','nism-8-z0','In Indian exchange-traded derivatives, which real-time margining system is mandated by SEBI for calculating portfolio risk?','["Value at Risk (VaR) single-stock static margin","Standard Portfolio Analysis of Risk (SPAN) margin","Simple Cash Margin 10%","Mark-to-Market overnight margin only"]',1,'SPAN (Standard Portfolio Analysis of Risk) margin evaluates overall portfolio risk across multiple price and volatility scan scenarios on a real-time intraday basis.',3) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q4','nism-8-z0','When an equity market moves into "Backwardation", what is the relationship between futures price and spot price?','["Futures price trades at a discount below spot price","Futures price trades at a significant premium above spot price","Futures price and spot price are exactly equal at all times","Option premiums become zero"]',0,'Backwardation occurs when the futures contract trades at a lower price than the spot price, often due to high expected dividend payouts or strong bearish sentiment.',4) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-8-z0-q5','nism-8-z0','Which options strategy involves buying an At-the-Money (ATM) call and an At-the-Money (ATM) put with the same strike price and expiration date?','["Bull Call Spread","Long Straddle","Iron Condor","Covered Call"]',1,'A Long Straddle consists of buying a call and a put at the same strike and expiration, profiting from large price movements in either direction (high volatility).',5) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
